Algorithm Week
  Dimension temperatures[7] As Integer;
  Define sum As Integer <- 0;
  For i <- 0 To 7 Do
    Read temperatures[i];
    sum <- sum + temperatures[i];
  EndFor
  Write sum;
EndAlgorithm

